import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"]
    cdc = inputs["cdc_events"]
    wm = inputs["watermark"]

    # Determine watermark high_ts
    if len(wm) > 0:
        high_ts = wm["high_ts"].max()
    else:
        # No watermark means nothing has been applied yet
        high_ts = pd.Timestamp.min

    # Filter events strictly after the watermark
    events = cdc[cdc["event_ts"] > high_ts].copy()

    # Apply sequentially by (event_ts, event_seq)
    events = events.sort_values(["event_ts", "event_seq"], kind="mergesort")

    # Build initial state from target_snapshot
    state = {}
    for _, row in target.iterrows():
        state[row["user_id"]] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"],
        }

    seven_days = pd.Timedelta(days=7)

    for _, ev in events.iterrows():
        uid = ev["user_id"]
        op = ev["op"]
        ts = ev["event_ts"]
        email = ev["email"]

        cur = state.get(uid)

        if op == "D":
            # Soft delete: status -> DELETED, status_ts -> ts, email preserved
            if cur is not None:
                new_email = cur["email"]
            else:
                # No prior state to preserve email from; fall back to event email
                new_email = email
            state[uid] = {"email": new_email, "status": "DELETED", "status_ts": ts}

        elif op == "U":
            if cur is None or cur["status"] == "ACTIVE":
                # Upsert on new or active user
                state[uid] = {"email": email, "status": "ACTIVE", "status_ts": ts}
            else:
                # cur status == 'DELETED'
                if (ts - cur["status_ts"]) > seven_days:
                    # Resurrection: strictly more than 7 days after deletion ts
                    state[uid] = {"email": email, "status": "ACTIVE", "status_ts": ts}
                # else: discard the update (sticky deletion window)
        # unknown ops are ignored (not specified)

    # Build output DataFrame
    rows = []
    for uid, s in state.items():
        rows.append(
            {
                "user_id": uid,
                "email": s["email"],
                "status": s["status"],
                "status_ts": s["status_ts"],
            }
        )

    result = pd.DataFrame(rows, columns=["user_id", "email", "status", "status_ts"])

    if len(result) > 0:
        result["user_id"] = result["user_id"].astype("int64")
        result["status_ts"] = pd.to_datetime(result["status_ts"]).astype("datetime64[us]")
        result["email"] = result["email"].astype(object)
        result["status"] = result["status"].astype(object)
    else:
        result = pd.DataFrame(
            {
                "user_id": pd.Series(dtype="int64"),
                "email": pd.Series(dtype=object),
                "status": pd.Series(dtype=object),
                "status_ts": pd.Series(dtype="datetime64[us]"),
            }
        )

    return {"new_snapshot": result}
